#include <moe_topk/protocol_i_ucmp.h>
#include <FSS/freekey.h>
#include <stdexcept>
#include <cstring>
namespace moe_topk { namespace { void valid(int b){if(b<34||b>53)throw std::invalid_argument("comparison_bits must be 34..53");} }
ProtocolIUcmpMaterial::ProtocolIUcmpMaterial(int b,std::uint64_t ml,std::uint64_t mr):bits_(b){valid(b);ring_mask_=(UINT64_C(1)<<b)-1;if((ml&~ring_mask_)||(mr&~ring_mask_))throw std::invalid_argument("mask outside ring");alpha_=(ml-mr)&ring_mask_;auto p=keyGenDCF(b,64,alpha_,1);keys_[0]=p.first;keys_[1]=p.second;live_=true;}
ProtocolIUcmpMaterial::~ProtocolIUcmpMaterial(){if(live_){auto pair=std::make_pair(keys_[0],keys_[1]);freeDCFKeyPackPair(pair);}}
ProtocolIUcmpMaterial::ProtocolIUcmpMaterial(ProtocolIUcmpMaterial&& o) noexcept { *this=std::move(o); }
ProtocolIUcmpMaterial& ProtocolIUcmpMaterial::operator=(ProtocolIUcmpMaterial&& o) noexcept {if(this!=&o){if(live_){auto pair=std::make_pair(keys_[0],keys_[1]);freeDCFKeyPackPair(pair);}bits_=o.bits_;ring_mask_=o.ring_mask_;alpha_=o.alpha_;keys_[0]=o.keys_[0];keys_[1]=o.keys_[1];live_=o.live_;used_[0]=o.used_[0];used_[1]=o.used_[1];o.live_=false;}return *this;}
std::uint64_t ProtocolIUcmpMaterial::eval_strict_lt(int party,std::uint64_t zl,std::uint64_t zr){if(!live_||party<0||party>1||used_[party])throw std::invalid_argument("invalid or consumed uCMP material");if((zl&~ring_mask_)||(zr&~ring_mask_))throw std::invalid_argument("masked operand outside ring");used_[party]=true; std::uint64_t x=(zl-zr)&ring_mask_, half=UINT64_C(1)<<(bits_-1), y=(x-half)&ring_mask_;GroupElement t1=0,t2=0;evalDCF(party,&t1,x,keys_[party]);evalDCF(party,&t2,y,keys_[party]);std::uint64_t ge=t2-t1;if(party==1&&y>=half)++ge;return party==0?UINT64_C(1)-ge:UINT64_C(0)-ge;}
ProtocolIUcmpPartyMaterial ProtocolIUcmpMaterial::export_party_material(int p)const{if(!live_||p<0||p>1)throw std::invalid_argument("invalid party");return ProtocolIUcmpPartyMaterial(p,keys_[p]);}
ProtocolIUcmpPartyMaterial::ProtocolIUcmpPartyMaterial(int p,const DCFKeyPack&x):party_(p),bits_(x.Bin),k_(x.k,x.k+x.Bin+1),g_(x.g,x.g+x.groupSize),v_(x.v,x.v+x.Bin*x.groupSize){if(p<0||p>1||bits_<34||bits_>53||x.Bout!=64||x.groupSize!=1)throw std::invalid_argument("invalid party material");}
std::uint64_t ProtocolIUcmpPartyMaterial::eval_strict_lt(std::uint64_t zl,std::uint64_t zr){if(party_<0||used_)throw std::invalid_argument("consumed party material");auto rm=(UINT64_C(1)<<bits_)-1;if((zl&~rm)||(zr&~rm))throw std::invalid_argument("operand outside ring");used_=true;auto x=(zl-zr)&rm,h=UINT64_C(1)<<(bits_-1),y=(x-h)&rm;DCFKeyPack q(bits_,64,1,k_.data(),g_.data(),v_.data());GroupElement a=0,b=0;evalDCF(party_,&a,x,q);evalDCF(party_,&b,y,q);auto ge=b-a;if(party_==1&&y>=h)++ge;return party_==0?UINT64_C(1)-ge:UINT64_C(0)-ge;}
std::vector<std::uint8_t> ProtocolIUcmpPartyMaterial::serialize()const{if(party_<0||used_)throw std::invalid_argument("material unavailable");std::vector<std::uint8_t>o={'M','2','U','C',1,(std::uint8_t)party_,(std::uint8_t)bits_,64,1};auto put=[&](std::uint64_t x){for(int i=7;i>=0;--i)o.push_back(x>>(i*8));};put(k_.size());put(g_.size());put(v_.size());for(auto b:k_){std::uint8_t t[16];std::memcpy(t,&b,16);o.insert(o.end(),t,t+16);}for(auto x:g_)put(x);for(auto x:v_)put(x);return o;}
ProtocolIUcmpPartyMaterial ProtocolIUcmpPartyMaterial::deserialize(const std::vector<std::uint8_t>&in){if(in.size()<33||in[0]!='M'||in[1]!='2'||in[2]!='U'||in[3]!='C'||in[4]!=1||in[7]!=64||in[8]!=1)throw std::invalid_argument("material header");size_t p=9;auto get=[&](){if(p+8>in.size())throw std::invalid_argument("material truncated");std::uint64_t x=0;for(int i=0;i<8;++i)x=(x<<8)|in[p++];return x;};int party=in[5],bits=in[6];auto nk=get(),ng=get(),nv=get();if(party<0||party>1||bits<34||bits>53||nk!=bits+1||ng!=1||nv!=bits||in.size()!=p+16*nk+8*ng+8*nv)throw std::invalid_argument("material length");ProtocolIUcmpPartyMaterial r;r.party_=party;r.bits_=bits;r.k_.resize(nk);r.g_.resize(ng);r.v_.resize(nv);for(auto&b:r.k_){std::memcpy(&b,in.data()+p,16);p+=16;}for(auto&x:r.g_)x=get();for(auto&x:r.v_)x=get();return r;}
}
